-- Scenario 73c2: SAP removes NOTIFICATIONTEXT, a column L1 does not use.
-- Expected: guarded L1 and L2 unaffected (WARNING only); the L0 view V_NOTIFICATION_EQUIPMENT,
-- which names the column, breaks inside the CLD. Unguarded: select * - see 75_observe.sql.
alter table {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION drop column NOTIFICATIONTEXT;

insert into {{DEMO_DB}}.CONTROL.SCHEMA_CHANGE_LOG (SCENARIO, EVENT, GUARDRAIL, DETAIL, SOURCE)
values ('73c2', 'SCENARIO_RUN', null, 'SAP removed column MAINT_NOTIFICATION.NOTIFICATIONTEXT (not used by L1)', 'PRESENTER');
